/**
 * Stringify JSON but with BigInt support.
 * @param value
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function stringifyJSON(value: any): string {
	return JSON.stringify(value, (_k, v) => {
		if (typeof v === "bigint") {
			return v.toString(); // Convert BigInt to a string
		}
		return v; // Return other values unchanged
	});
}
